        self.hidden = nn.Sequential(nn.Flatten(), nn.Linear(96 * 3 * 3, 139), nn.BatchNorm1d(139), nn.GELU(), nn.Dropout(0.15))
        self.experts = nn.Linear(139, 3 * 10)
        self.gates = nn.Linear(139, 3 * 10)

    def forward(self, features: torch.Tensor) -> torch.Tensor:
        hidden = self.hidden(features)
        expert_logits = self.experts(hidden).view(-1, 3, 10)
        expert_weights = F.softmax(self.gates(hidden).view(-1, 3, 10), dim=1)
        return (expert_logits * expert_weights).sum(dim=1)

